package com.rikkeibank.transaction.web;import com.rikkeibank.transaction.domain.BankTransaction;import com.rikkeibank.transaction.service.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.ZoneId;import java.util.*;
@RestController public class TransactionController{private final TransferSagaService saga;private final TransactionQueryService query;public TransactionController(TransferSagaService s,TransactionQueryService q){saga=s;query=q;}@PostMapping("/api/transfers")@PreAuthorize("hasRole('CUSTOMER')")@ResponseStatus(HttpStatus.CREATED)BankTransaction transfer(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody TransferRequest r){return saga.transfer(r.sourceAccountId(),r.targetAccountId(),UUID.fromString(jwt.getClaimAsString("customerId")),r.amount(),r.simulateCreditFailure());}@GetMapping("/api/transactions/mine")@PreAuthorize("hasRole('CUSTOMER')")List<BankTransaction>mine(@AuthenticationPrincipal Jwt jwt){return query.mine(UUID.fromString(jwt.getClaimAsString("customerId")));}@GetMapping("/api/transactions/today")@PreAuthorize("hasRole('TELLER')")List<BankTransaction>today(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="Asia/Bangkok")String zone){return query.today(UUID.fromString(jwt.getSubject()),ZoneId.of(zone));}@GetMapping("/api/transactions/{id}")@PreAuthorize("hasRole('ADMIN') or @transactionAuthorization.canRead(#id,authentication)")BankTransaction get(@PathVariable UUID id){return query.get(id);}@PatchMapping("/api/transactions/{id}/assign/{tellerId}")@PreAuthorize("hasRole('ADMIN')")BankTransaction assign(@PathVariable UUID id,@PathVariable UUID tellerId){return query.assign(id,tellerId);}public record TransferRequest(@NotNull UUID sourceAccountId,@NotNull UUID targetAccountId,@NotNull @Positive BigDecimal amount,boolean simulateCreditFailure){}}

